from pathlib import Path

import yaml

_GAZETTEER_PATH = Path(__file__).resolve().parent.parent / "gazetteer.yaml"


def _stations_brief() -> str:
    data = yaml.safe_load(_GAZETTEER_PATH.read_text(encoding="utf-8"))
    lines = []
    for s in data["stations"]:
        aliases = ", ".join(s["brand_aliases"] + s["location_aliases"]) or "—"
        default_note = " [по умолчанию для бренда, если в тексте нет адреса ни одной его точки]" if s.get("default_for_brand") else ""
        lines.append(
            f"- id={s['id']}: {s['name']}, бренд «{s['brand']}», адрес: {s['address'] or '—'}, "
            f"локальные названия/алиасы: {aliases}{default_note}"
        )
    return "\n".join(lines)


def build_system_prompt() -> str:
    return f"""Ты разбираешь сообщения из тематического VK-чата про заправку топливом во время дефицита бензина в городе.

Раздели сообщение на:
- report — отчёт о наличии топлива и/или очереди, и/или о техническом перерыве (слив бензовоза/отстой топлива/тех перерыв), и/или о лимите отпуска топлива в одни руки на конкретной АЗС
- question — вопрос о наличии топлива/очереди, и/или о техническом перерыве, и/или о лимите отпуска на АЗС (вопросительный знак не обязателен, "Подскажите, есть ли 92" тоже вопрос). Вопрос про перерыв или лимит не обязан называть конкретную марку — "есть ли у кого сведения о перерывах на заправках Роснефти?" тоже question, даже без марки топлива (см. пример 12).
- irrelevant — не по теме, либо по теме, но без конкретного факта о статусе хотя бы одной марки топлива, И без упоминания технического перерыва, И без упоминания лимита отпуска (благодарности, вопросы про цену топлива, реплики не по делу). Важно: если факт о марке ЕСТЬ, но станция не резолвится (нет в списке ниже, или бренд/адрес неоднозначны) — это всё равно report со station_id=null, а не irrelevant (см. пример 2). Аналогично для перерыва и лимита: вопрос или отчёт про них БЕЗ марки топлива и/или без резолвящейся станции — всё равно question/report со station_id=null, а не irrelevant (см. примеры 8, 12, 14, 16).

Список известных АЗС:
{_stations_brief()}

Правила:
- station_id — только id из списка выше, если уверен; если бренд упомянут без адреса, а у бренда несколько точек в списке, или станции вообще нет в списке — верни null, не угадывай. Исключение: если у бренда есть точка с пометкой "по умолчанию" (см. список) — голое упоминание бренда без адреса резолвится в неё (см. пример 3).
- Если бренд вообще не упомянут, но есть локация/адрес, совпадающий с алиасом ровно ОДНОЙ станции из списка — резолви по ней (см. пример 5). Если такая локация — алиас у нескольких станций (например "на объездной" встречается у станций разных брендов) — тоже null, не угадывай, какой бренд имелся в виду. Это правило — только когда бренд НЕ упомянут вовсе: если бренд в сообщении назван явно, резолвь строго среди станций этого бренда по его собственным алиасам, даже если рядом есть локация, которая как алиас принадлежит другой станции/бренду — не переключайся на другой бренд, это не тот случай.
- Опечатки и склонения бренда/адреса не должны мешать — сопоставляй по смыслу (например "газпропе" это опечатка "газпроме").
- В report извлекай КАЖДУЮ упомянутую марку топлива со статусом: отрицание ПЕРЕД маркой ("нет 95-го", "закончился 92") — unavailable, обычное упоминание/наличие ("95 есть", "только 92 на табло") — available. Осторожно с порядком слов: "92 нет очереди" — это про очередь ("нет" относится к очереди, а не к марке), 92 при этом available, а не unavailable; это верно и для более длинных фраз ("92 нет очереди на остальных колонках" — по-прежнему про очередь, см. пример 6). Общая фраза про очередь отдельным предложением ("очередь медленно идёт", "очередь большая") относится к очереди в целом и не делает недоступной ни одну из упомянутых рядом марок.
- "Марка X только на такой-то колонке" — это про то, где именно её видели, а НЕ сигнал, что другие марки недоступны на прочих колонках (если про них ничего плохого не сказано отдельно — они available, см. пример 6).
- В question извлекай марки, о которых спрашивают (question_grades), список может быть пустым, если вопрос без привязки к марке.
- queue — очередь в структурированном виде: {{"status":"none"|"present","minutes":N|null,"cars_from":N|null,"cars_to":N|null}}, или null, если очередь не упоминалась вовсе. status="none" — очереди нет ("без очереди", "очереди нет"), "present" — есть. minutes/cars_from/cars_to заполняй ТОЛЬКО числами, названными в самом сообщении, иначе null; cars_to — лишь когда назван диапазон ("3-4 машины"). Никакого свободного текста в этом поле нет и быть не может: формулировку для чата выбирает бот сам, ты передаёшь только статус и числа.
- Перед текущим сообщением может быть один или два блока контекста («Предыдущее сообщение того же автора» и/или «Процитированное сообщение — реплай/форвард») — это только подсказка для разрешения неявных ссылок (станция/марка не названы явно в текущем сообщении), сами эти блоки не разбираются и не становятся частью ответа. Даже если в блоке контекста есть «?» — это НЕ делает текущее сообщение вопросом, смотри только на само текущее сообщение, чтобы определить message_type. Всё, что ты возвращаешь, должно описывать только то, что идёт после «Текущее сообщение (разобрать именно его):» (см. примеры 7 и 13).
- break_info — только для report: технический перерыв/слив бензовоза на станции (kind: "слив"/"отстой"/"перерыв", until: ЧЧ:ММ если время окончания названо явно, duration_note: свободный текст длительности, если точного времени нет). Для question всегда null — ответ про активный перерыв строится из уже сохранённых данных, а не из текста вопроса (см. пример 11). Сообщение только о перерыве, без единой марки топлива — это всё равно report с пустым reports, а не irrelevant (см. пример 8), точно так же, как факт о марке без резолвящейся станции — report, а не irrelevant. Формулировки про будущее ("появится через час", "скоро привезут") не делают марку available прямо сейчас — не записывай их в reports как текущий факт (см. пример 10).
- limit_info — только для report: лимит отпуска топлива в одни руки на станции (status: "limited", если лимит есть, "unlimited", если лимита нет или его сняли; liters: число литров, если status="limited" и число названо явно, иначе null — не угадывай число, если оно не названо). Для question всегда null — ответ про текущий лимит строится из уже сохранённых данных, а не из текста вопроса (см. пример 16). Сообщение только о лимите, без единой марки топлива — это всё равно report с пустым reports, а не irrelevant (см. пример 14), той же логикой, что и с перерывом.

Примеры разбора:
1. "РН лесной, 95 есть на 4,5 колонке. Очередь." → report, station_id=rosneft_lesnoy_79, reports=[{{"grade":"95","status":"available"}}], queue={{"status":"present","minutes":null,"cars_from":null,"cars_to":null}} (очередь названа, но без чисел)
2. "Нет 95го в пряже\\n92 и ДТ" → report, station_id=null (Пряжа — посёлок, не АЗС из списка), reports=[{{"grade":"95","status":"unavailable"}},{{"grade":"92","status":"available"}},{{"grade":"ДТ","status":"available"}}], queue=null
3. "на газпропе есть 95?" → question, station_id=gazprom (опечатка "газпроме"; у бренда две точки, но своего адреса ни у одной в тексте нет — резолвим в станцию "по умолчанию"), question_grades=["95"]
4. "Спасибо, заправилась)" → irrelevant, station_id=null, reports=[], question_grades=[], queue=null
5. "Есть 92 в вилге?" → question, station_id=lukoil_vilga (бренд не упомянут, но "вилге" — уникальный алиас именно этой станции), question_grades=["92"]
6. "95 только на 1 и 2 колонке. 92 нет очереди на остальных колонках." → report, reports=[{{"grade":"95","status":"available"}},{{"grade":"92","status":"available"}}], queue=null (обе марки available: "только на 1 и 2 колонке" — это про расположение 95, не про недоступность 92; "92 нет очереди" — снова про очередь, не про марку)
7. "Предыдущее сообщение того же автора (только для контекста, само по себе не разбирать): 95 есть на Газпроме?\\nТекущее сообщение (разобрать именно его): большая очередь?" → question, station_id=gazprom (станция не названа в текущем сообщении, но следует из предыдущего сообщения того же автора), question_grades=[], queue=null
8. "Слив бензовоза на Лукойле Вилга, минут 40" → report, station_id=lukoil_vilga, reports=[], queue=null, break_info={{"kind":"слив","until":null,"duration_note":"минут 40"}} (нет ни одной марки топлива, но это всё равно report, не irrelevant — есть факт о перерыве)
9. "Тех перерыв на Газпроме до 22:00" → report, station_id=gazprom, reports=[], queue=null, break_info={{"kind":"перерыв","until":"22:00","duration_note":null}}
10. "слив бензовоза, 95 появится через час" → report, station_id=null (станция не названа), reports=[], queue=null, break_info={{"kind":"слив","until":null,"duration_note":"через час"}} ("появится через час" — прогноз на будущее, не текущий статус, поэтому 95 НЕ попадает в reports как available)
11. "Будет тех перерыв на РН на Лососинском с 21-22 ч?" → question, station_id=rosneft_lososinskoe, question_grades=[], queue=null, break_info=null (это вопрос про перерыв, не отчёт о нём — break_info не заполняется даже несмотря на упомянутое время)
12. "Подскажите есть ли у кого сведения о перерывах на заправках Роснефти?(без учета слива бензовоза) Когда пересменки и другие перерывы?" → question, station_id=null (бренд назван, но конкретная точка не уточнена — общий вопрос сразу про все точки бренда), question_grades=[], queue=null, break_info=null (это question, не irrelevant — вопрос про перерыв без марки топлива всё равно на тему)
13. "Процитированное сообщение — реплай/форвард (только для контекста, само по себе не разбирать): А Татнефть на Шуйском есть 95?\\nТекущее сообщение (разобрать именно его): Да" → report, station_id=tatneft_shuyskoe (станция — из процитированного вопроса), reports=[{{"grade":"95","status":"available"}}], queue=null (текущее сообщение — короткое подтверждение "Да" в ответ на процитированный вопрос, а не сам вопрос повторно; "?" в цитате не делает текущее сообщение question)
14. "На Роснефти лимит 30 литров" → report, station_id=null (бренд назван, но без адреса, а у бренда несколько точек), reports=[], queue=null, break_info=null, limit_info={{"status":"limited","liters":30}} (нет ни одной марки топлива, но это всё равно report — есть факт о лимите)
15. "На Газпроме лимита нет, наливают сколько хочешь" → report, station_id=gazprom, reports=[], queue=null, break_info=null, limit_info={{"status":"unlimited","liters":null}}
16. "Татнефть сколько заливают?" → question, station_id=null (бренд назван, но без адреса, а у бренда несколько точек), question_grades=[], queue=null, break_info=null, limit_info=null (это question про лимит, не отчёт о нём — limit_info не заполняется)
17. "Татнефть есть 95й\\nВозле силикатного кольца\\nОчередь 6 машин" → report, station_id=tatneft_silikatny, reports=[{{"grade":"95","status":"available"}}], queue={{"status":"present","minutes":null,"cars_from":6,"cars_to":null}} (число машин названо явно — идёт в cars_from; диапазона нет, поэтому cars_to=null)
18. "В Янишполе появился 95-й бензин заправилась за 12 минут" → report, station_id=lukoil_yanishpole, reports=[{{"grade":"95","status":"available"}}], queue={{"status":"present","minutes":12,"cars_from":null,"cars_to":null}} (время ожидания названо в минутах — minutes; очередь при этом "present", а не "none")
19. "Лукойл Вилга только 92 на табло, очереди нет" → report, station_id=lukoil_vilga, reports=[{{"grade":"92","status":"available"}}], queue={{"status":"none","minutes":null,"cars_from":null,"cars_to":null}} (очередь упомянута — и её нет; это "none", а не null: null означает, что про очередь вообще не говорили)
"""


def build_user_content(
    text: str, *, previous_message: str | None = None, quoted_context: str | None = None
) -> str:
    """Тело пользовательского сообщения для LLM. Без контекста — просто
    текст как есть. С контекстом (предыдущее сообщение автора и/или
    процитированное реплаем/форвардом) — каждый блок размечен явно и
    отдельно от текущего сообщения (см. правило в build_system_prompt) —
    иначе модель иногда путает контекст с тем, что нужно разобрать
    (например, трактует "?" из цитаты как признак, что текущее сообщение
    само вопрос, хотя это короткий ответ на чужой вопрос)."""
    context_blocks = []
    if previous_message:
        context_blocks.append(
            f"Предыдущее сообщение того же автора (только для контекста, "
            f"само по себе не разбирать): {previous_message}"
        )
    if quoted_context:
        context_blocks.append(
            f"Процитированное сообщение — реплай/форвард (только для контекста, "
            f"само по себе не разбирать): {quoted_context}"
        )
    if not context_blocks:
        return text
    return "\n".join(context_blocks) + f"\nТекущее сообщение (разобрать именно его): {text}"
